CID = 'errors'
KINDS, TRACE, COMMON, TRY, ELSE, RAISE, REAL = "Two kinds of errors", "Reading a traceback", "The common exceptions", "try and except", "else and finally", "raise: create your own errors", "Real uses"
def W(lv, sec, q, starter, sol, e): return dict(lv=lv, ty='code', sec=sec, q=q, starter=starter, sol=sol, e=e)
def F(lv, sec, q, c, fixed, e): return dict(lv=lv, ty='fix', sec=sec, q=q, c=c, fixed=fixed, e=e)
def T(lv, sec, c, e): return dict(lv=lv, ty='type', sec=sec, q="Type exactly what this code prints.", c=c, e=e)
Q = [
 # ---------- Basic ----------
 T(1, TRY, 'try:\n    print(int("42") + 1)\nexcept ValueError:\n    print("bad")', "Nothing goes wrong inside `try`, so the `except` block is skipped."),
 W(1, TRY, '`text = "abc"`. Convert it to an int inside `try`. If that gives a `ValueError`, print `Not a number`.', 'text = "abc"\n', 'text = "abc"\ntry:\n    print(int(text))\nexcept ValueError:\n    print("Not a number")', "`int(\"abc\")` raises `ValueError`. The `except ValueError:` block catches it and the program carries on."),
 W(1, TRY, '`d = 0`. Print `10 / d` inside `try`, and print `Cannot divide by zero` if a `ZeroDivisionError` happens.', 'd = 0\n', 'd = 0\ntry:\n    print(10 / d)\nexcept ZeroDivisionError:\n    print("Cannot divide by zero")', "Name the exact error you expect after `except`."),
 W(1, COMMON, 'The starter has three small functions that each fail in a different way. Call each one inside `try`, and in `except Exception as e:` print the name of the error with `type(e).__name__`.', 'tests = [lambda: int("x"), lambda: [1, 2][5], lambda: {"a": 1}["b"]]\n', 'tests = [lambda: int("x"), lambda: [1, 2][5], lambda: {"a": 1}["b"]]\nfor t in tests:\n    try:\n        t()\n    except Exception as e:\n        print(type(e).__name__)', "`Exception` catches almost every error. `type(e).__name__` gives its name: a bad conversion, an index past the end, a missing key."),
 F(1, TRY, "This code should print `Cannot divide`, but it crashes. Fix the except line.", 'try:\n    print(10 / 0)\nexcept ValueError:\n    print("Cannot divide")', 'try:\n    print(10 / 0)\nexcept ZeroDivisionError:\n    print("Cannot divide")', "`except ValueError` only catches a `ValueError`. Dividing by 0 raises `ZeroDivisionError`, so name that one."),
 T(1, ELSE, 'try:\n    x = 5\nexcept ValueError:\n    print("error")\nelse:\n    print("ok", x)\nfinally:\n    print("done")', "`else` runs when there was no error. `finally` runs every time, error or not."),
 W(1, RAISE, 'Write `set_price(p)` that raises `ValueError("Price must be positive")` when `p` is 0 or less, and returns `p` otherwise. Call `set_price(0)` inside `try` and print `Error: Price must be positive`.', '# def set_price(p):\n', 'def set_price(p):\n    if p <= 0:\n        raise ValueError("Price must be positive")\n    return p\n\ntry:\n    set_price(0)\nexcept ValueError as e:\n    print("Error:", e)', "`raise` creates the error yourself. `except ... as e` gives you the error, and printing `e` shows its message."),
 F(1, KINDS, "This code should print `hi`. The `try` does not help here. Fix the real problem.", 'try:\n    print("hi"\nexcept SyntaxError:\n    print("fixed")', 'try:\n    print("hi")\nexcept SyntaxError:\n    print("fixed")', "A syntax error stops Python before anything runs, so `try` cannot catch it. Only runtime errors can be caught. Close the bracket."),
 # ---------- Medium ----------
 W(2, REAL, '`readings = ["12.5", "x", "13", "--", "11.5"]`. Convert each with `float()` inside `try`, skip the bad ones, and print the clean list and how many were skipped.', 'readings = ["12.5", "x", "13", "--", "11.5"]\n', 'readings = ["12.5", "x", "13", "--", "11.5"]\nclean = []\nskipped = 0\nfor r in readings:\n    try:\n        clean.append(float(r))\n    except ValueError:\n        skipped += 1\nprint(clean, skipped)', "A `try` inside the loop handles each value on its own, so one bad value does not stop the rest."),
 T(2, ELSE, 'def f(n):\n    try:\n        r = 10 / n\n    except ZeroDivisionError:\n        return "zero"\n    else:\n        return r\n    finally:\n        print("checked", n)\n\nprint(f(2))\nprint(f(0))', "`finally` runs just before the function returns, so `checked` is printed before each result."),
 W(2, TRY, 'Try `int("12a")`, catch it with `except ValueError as e`, and print `Error:` followed by the message.', '# try / except ValueError as e\n', 'try:\n    int("12a")\nexcept ValueError as e:\n    print("Error:", e)', "The error object carries Python's own message, which is handy in logs."),
 W(2, TRY, 'Write `safe_get(d, key)` that returns `d[key]`, or `"missing"` if that raises a `KeyError`. Print `safe_get({"a": 1}, "a")` and `safe_get({"a": 1}, "b")` with one `print()`.', '# def safe_get(d, key):\n', 'def safe_get(d, key):\n    try:\n        return d[key]\n    except KeyError:\n        return "missing"\n\nprint(safe_get({"a": 1}, "a"), safe_get({"a": 1}, "b"))', "A `try` inside a function can turn an error into a normal return value."),
 F(2, REAL, "This check should pass and print `Check passed`, because the total really is 60. Fix the assert.", 'total = sum([10, 20, 30])\nassert total == 50, "Total should be 60"\nprint("Check passed")', 'total = sum([10, 20, 30])\nassert total == 60, "Total should be 60"\nprint("Check passed")', "`assert` stops the program with an `AssertionError` when its check is `False`. The check itself was wrong."),
 T(2, TRY, 'try:\n    print("A")\n    x = {"a": 1}["b"]\n    print("B")\nexcept KeyError:\n    print("C")\nprint("D")', "The error happens on the second line, so `B` is skipped. After the `except` block, the program carries on."),
 W(2, RAISE, 'Write `withdraw(balance, amount)` that raises `ValueError("Insufficient funds")` when `amount` is more than `balance`, and returns the new balance otherwise. For the pairs `(500, 200)` and `(500, 800)`, print the result or `Error: Insufficient funds`.', '# def withdraw(balance, amount):\n', 'def withdraw(balance, amount):\n    if amount > balance:\n        raise ValueError("Insufficient funds")\n    return balance - amount\n\nfor balance, amount in [(500, 200), (500, 800)]:\n    try:\n        print(withdraw(balance, amount))\n    except ValueError as e:\n        print("Error:", e)', "The function only reports the problem. The caller decides what to do with it."),
 W(2, COMMON, 'For each value in `["5", "x", None]`, try `int(value)` and print `ok` or `bad`. Catch both `ValueError` and `TypeError` in ONE `except`.', 'values = ["5", "x", None]\n', 'values = ["5", "x", None]\nfor v in values:\n    try:\n        int(v)\n        print("ok")\n    except (ValueError, TypeError):\n        print("bad")', "`int(\"x\")` is a `ValueError` and `int(None)` is a `TypeError`. A tuple after `except` catches both."),
 F(2, RAISE, "This code should print `Error: Negative age`. Fix the raise line.", 'def check(age):\n    if age < 0:\n        raise "Negative age"\n\ntry:\n    check(-1)\nexcept Exception as e:\n    print("Error:", e)', 'def check(age):\n    if age < 0:\n        raise ValueError("Negative age")\n\ntry:\n    check(-1)\nexcept Exception as e:\n    print("Error:", e)', "You can only raise an error object, like `ValueError(\"message\")`, not plain text."),
 W(2, TRACE, '`menu = {"tea": 20}`. A traceback showed `KeyError: \'coffee\'` from `menu[item]`. Write `get_price(item)` that returns the price, or 0 when the item is missing, using `get()` instead of `try`. Print `get_price("tea")` and `get_price("coffee")`.', 'menu = {"tea": 20}\n', 'menu = {"tea": 20}\n\ndef get_price(item):\n    return menu.get(item, 0)\n\nprint(get_price("tea"), get_price("coffee"))', "Reading the traceback tells you the line and the cause. Often the best fix avoids the error altogether."),
 # ---------- Challenge (same chapter, combined) ----------
 W(3, REAL, 'Pretend the user typed `typed = ["", "abc", "-3", "7"]`. Go through them and find the first whole number from 1 to 10, using `try/except ValueError` and a range check. Print `Invalid entry` for each bad one, then `OK: 7`.', 'typed = ["", "abc", "-3", "7"]\n', 'typed = ["", "abc", "-3", "7"]\nfor raw in typed:\n    try:\n        n = int(raw)\n        if 1 <= n <= 10:\n            print("OK:", n)\n            break\n        print("Invalid entry")\n    except ValueError:\n        print("Invalid entry")', "Two kinds of bad input: text that is not a number (caught by `except`) and numbers out of range (caught by the `if`)."),
 W(3, ELSE, 'For each item in `["10", "20", "x", "30"]`: convert it in `try`, count it as bad in `except`, and add it to the total in `else`. Then print the total, the number of bad items and the average of the good ones.', 'items = ["10", "20", "x", "30"]\n', 'items = ["10", "20", "x", "30"]\ntotal = 0\ngood = 0\nbad = 0\nfor item in items:\n    try:\n        n = int(item)\n    except ValueError:\n        bad += 1\n    else:\n        total += n\n        good += 1\nprint(total, bad, total / good)', "Keep the `try` block small (only the risky line). The work that should happen only on success goes in `else`."),
 W(3, RAISE, 'Write `parse_score(text)`: convert it with `int()` (let its `ValueError` happen), then raise `ValueError("Out of range")` if it is not from 0 to 100. For `["85", "105", "abc"]`, print the score or `Error:` with the message.', '# def parse_score(text):\n', 'def parse_score(text):\n    score = int(text)\n    if not 0 <= score <= 100:\n        raise ValueError("Out of range")\n    return score\n\nfor text in ["85", "105", "abc"]:\n    try:\n        print(parse_score(text))\n    except ValueError as e:\n        print("Error:", e)', "Both problems come out as a `ValueError`, so one `except` handles them, and the message says which one it was."),
 T(3, ELSE, 'def f():\n    try:\n        return "try"\n    finally:\n        print("finally runs")\n\nprint(f())', "Even when `try` returns, `finally` still runs first. Then the returned value is printed."),
 F(3, TRY, "This code should print `25.0`, `cannot divide by zero` and `not a number`. Fix it so every value is handled.", 'nums = ["4", "0", "x"]\nfor n in nums:\n    try:\n        print(100 / int(n))\n    except ValueError:\n        print("not a number")', 'nums = ["4", "0", "x"]\nfor n in nums:\n    try:\n        print(100 / int(n))\n    except ZeroDivisionError:\n        print("cannot divide by zero")\n    except ValueError:\n        print("not a number")', "One `try` can have several `except` blocks, one per kind of error."),
 W(3, COMMON, 'Write `to_number(text)` that returns an int if it can, otherwise a float if it can, otherwise `None` (use a `try` inside an `except`). Print `[to_number(x) for x in ["7", "7.5", "seven"]]`.', '# def to_number(text):\n', 'def to_number(text):\n    try:\n        return int(text)\n    except ValueError:\n        try:\n            return float(text)\n        except ValueError:\n            return None\n\nprint([to_number(x) for x in ["7", "7.5", "seven"]])', "Try the strictest conversion first. If it fails, fall back to the next one."),
 W(3, REAL, 'Write `average(values)` that uses `assert` to check the list is not empty (message `No values`), then returns the average. Call `average([])` in `try/except AssertionError as e` and print `Error: No values`. Then print `average([4, 6])`.', '# def average(values):\n', 'def average(values):\n    assert len(values) > 0, "No values"\n    return sum(values) / len(values)\n\ntry:\n    average([])\nexcept AssertionError as e:\n    print("Error:", e)\nprint(average([4, 6]))', "`assert` is a quick way to state what must be true. When it fails, it raises `AssertionError` with your message."),
]
